            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except FileNotFoundError:
            pass
        raise


def read_json(path):
    with open(path, encoding="utf-8") as f:
        return json.load(f)


def list_json(directory):
    """Names of the *.json files in directory (hidden and temp files skipped)."""
    if not os.path.isdir(directory):
        return []
    return sorted(
        name for name in os.listdir(directory)
        if name.endswith(".json") and not name.startswith(".")
    )


def scratch_dir(root, purpose):
    """A new, uniquely named working directory for one operation under the scratch root.

    Never reuse a fixed name here: leftovers from an earlier operation would be
    picked up as if they were this operation's files.
    """
    os.makedirs(root, exist_ok=True)
    return tempfile.mkdtemp(prefix=f"{purpose}-", dir=root)


def copy_files(src_dir, dst_dir, names=None):
    os.makedirs(dst_dir, exist_ok=True)
    for name in names if names is not None else list_json(src_dir):
        shutil.copy2(os.path.join(src_dir, name), os.path.join(dst_dir, name))


def remove_files(directory, names):
    for name in names:
        try:
            os.remove(os.path.join(directory, name))
        except FileNotFoundError:
            pass
